308	// ── Scope custom CSS for admin preview — prefix selectors with #wid ─────────
309	// Handles @keyframes/@font-face (pass-through), @media (recursive scoping),
310	// and regular selectors (prefixed with container ID).
311	function scopeAdminCss(rawCss: string | null | undefined, wid: string): string {
312	  if (!rawCss) return "";
313	  // Sanitize the same way the public API does (mirrors api.widget-config.tsx)
314	  const css = rawCss
315	    .replace(/<style\b[^>]*>/gi, "")
316	    .replace(/<\/style>/gi, "")
317	    .replace(/@import\b[^;]*(;|$)/gi, "")
318	    .replace(/\bexpression\s*\(/gi, "")
319	    .replace(/url\s*\(\s*['"]?\s*javascript\s*:/gi, "url(")
320	    .replace(/url\s*\(\s*['"]?\s*data\s*:/gi, "url(");
321	  let result = "";
322	  let i = 0;
323	  while (i < css.length) {
324	    // Skip whitespace
325	    while (i < css.length && /\s/.test(css[i])) { result += css[i]; i++; }
326	    if (i >= css.length) break;
327	    // Handle at-rules
328	    if (css[i] === "@") {
