349	        if (j < css.length && css[j] === "{") {
350	          result += "{"; j++;
351	          let depth = 1; let inner = "";
352	          while (j < css.length && depth > 0) {
353	            if (css[j] === "{") depth++;
354	            if (css[j] === "}") depth--;
355	            if (depth > 0) inner += css[j];
356	            j++;
357	          }
358	          result += scopeAdminCss(inner, wid);
359	          result += "}";
