470	      colorClass = 'zcc-countdown--passed';
471	      text = 'Order now for next business day dispatch';
472	    } else {
473	      var totalMinutes = cd.hours * 60 + cd.minutes;
474	      if (totalMinutes > 180) colorClass = 'zcc-countdown--green';
475	      else if (totalMinutes > 60) colorClass = 'zcc-countdown--amber';
476	      else colorClass = 'zcc-countdown--red';
477	      text = 'Order within <strong>' + cd.hours + 'h ' + cd.minutes + 'm</strong> for same-day dispatch';
478	    }
479	    return '<div class="zcc-countdown ' + colorClass + '" id="' + widgetId + '-countdown">' + ICONS.clock + '<span>' + text + '</span></div>';
