690	  function wireWidget(wid, cfg, API_BASE, SHOP) {
691	    var inp = document.getElementById(wid + "-inp");
692	    var btn = document.getElementById(wid + "-btn");
693	    var res = document.getElementById(wid + "-res");
694	    if (!inp || !btn || !res) return;
695	
696	    function normalizeZip(raw) {
697	      var z = raw.trim().toUpperCase();
698	      z = z.replace(/\s+/g, '');        // collapse all spaces (UK: SW1A 2AA → SW1A2AA)
699	      z = z.replace(/-\d{4}$/, '');     // strip US ZIP+4 suffix (90210-1234 → 90210)
700	      return z;
701	    }
