706	    function setBtnLoading(loading) {
707	      btn.disabled = loading;
708	      if (loading) {
709	        btn.classList.add('zcc-btn--loading');
710	        // Replace entire button content with a lone spinner — no text overlap
711	        btn.innerHTML = '<span class="zcc-spinner" aria-hidden="true"></span>';
712	      } else {
713	        btn.classList.remove('zcc-btn--loading');
714	        // Restore original icon + label markup
715	        btn.innerHTML = btnOriginalHtml;
716	        // Keep button text in sync with config (merchant may have customised it)
717	        var labelEl = btn.querySelector('.zcc-btn-label');
718	        if (labelEl) labelEl.textContent = cfg.buttonText;
719	      }
720	    }
